import React from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { 
  Box, 
  Typography, 
  Button, 
  Paper, 
  useTheme, 
  useMediaQuery,
  Breadcrumbs,
  Link as MuiLink
} from '@mui/material';
import { 
  Add as AddIcon,
  Home as HomeIcon
} from '@mui/icons-material';
import AdminLayout from '../../../components/Layout/AdminLayout';
import AdminAppointmentList from '../../../components/AdminAppointmentList/AdminAppointmentList';
import { useQuery } from '@apollo/client';
import { GET_ALL_APPOINTMENTS } from '../../../graphql/admin';

const Appointments = () => {
  const navigate = useNavigate();
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));

  const { loading, error, data, refetch } = useQuery(GET_ALL_APPOINTMENTS, {
    fetchPolicy: 'network-only', // Always fetch fresh data
    onError: (error) => {
      console.error('Error loading appointments:', error);
    }
  });

  const handleNewAppointment = () => {
    navigate('/admin/appointments/new');
  };

  return (
    <AdminLayout>
      <Box 
        sx={{ 
          width: '100%',
          boxSizing: 'border-box',
          flexGrow: 1,
          display: 'flex',
          flexDirection: 'column',
          p: { xs: 2, sm: 3 },
          pt: 2
        }}
      >

        <Box 
          sx={{
            display: 'flex',
            flexDirection: { xs: 'column', sm: 'row' },
            justifyContent: 'flex-start',
            alignItems: { xs: 'stretch', sm: 'center' },
            gap: 2,
            width: '100%',
            mb: 3
          }}
        >
          <Typography variant="h4" component="h1" sx={{ fontWeight: 500, color: 'text.primary' }}>
            All Appointments
          </Typography>
          <Box sx={{ width: { xs: '100%', sm: 'auto' }, ml: { sm: 'auto' } }}>
            <Button
              variant="contained"
              color="primary"
              startIcon={<AddIcon />}
              onClick={handleNewAppointment}
              size={isMobile ? 'medium' : 'medium'}
              sx={{
                minWidth: 180,
                [theme.breakpoints.down('sm')]: {
                  width: '100%',
                  maxWidth: 'none',
                  mt: 1
                }
              }}
            >
              New Appointment
            </Button>
          </Box>
        </Box>

        <Box sx={{ 
          flex: 1,
          display: 'flex',
          flexDirection: 'column',
          pb: 3
        }}>
          <Paper 
            elevation={0}
            sx={{ 
              p: { xs: 2, sm: 3 },
              flex: 1,
              display: 'flex',
              flexDirection: 'column',
              backgroundColor: 'background.paper',
              borderRadius: 2,
              width: '100%',
              overflow: 'hidden',
              border: '1px solid',
              borderColor: 'divider'
            }}
          >
            <AdminAppointmentList 
              appointments={data?.allAppointments || []}
              loading={loading}
              error={error}
              onRefresh={() => refetch()}
            />
          </Paper>
        </Box>
      </Box>
    </AdminLayout>
  );
};

export default Appointments;
